svg=[]; pages=[]
def col(v):
 from reportlab.lib.colors import HexColor
 return HexColor(v)
def line(x1,y1,x2,y2,color=INK,width=1,dash=False):
 C.setStrokeColor(col(color));C.setLineWidth(width);C.setDash([5,4] if dash else []);C.line(x1,H-y1,x2,H-y2)
 svg.append(f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{width}"'+(' stroke-dasharray="5 4"' if dash else '')+'/>')
def rect(x,y,w,h,fill='none',stroke=INK,width=1):
 C.setLineWidth(width);C.setDash([]);C.setStrokeColor(col(stroke if stroke!='none' else '#ffffff'));C.setFillColor(col(fill if fill!='none' else '#ffffff'));C.rect(x,H-y-h,w,h,fill=int(fill!='none'),stroke=int(stroke!='none'))
 svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="{stroke}" stroke-width="{width}"/>')
def poly(pts,fill='none',stroke=INK,width=1):
 p=C.beginPath();p.moveTo(pts[0][0],H-pts[0][1]);[p.lineTo(x,H-y) for x,y in pts[1:]];p.close();C.setFillColor(col(fill if fill!='none' else '#ffffff'));C.setStrokeColor(col(stroke if stroke!='none' else '#ffffff'));C.setLineWidth(width);C.setDash([]);C.drawPath(p,fill=int(fill!='none'),stroke=int(stroke!='none'))
 svg.append(f'<polygon points="{" ".join(f"{x},{y}" for x,y in pts)}" fill="{fill}" stroke="{stroke}" stroke-width="{width}"/>')
def circle(x,y,r,fill='none',stroke=INK):
 C.setFillColor(col(fill if fill!='none' else '#ffffff'));C.setStrokeColor(col(stroke));C.setLineWidth(1);C.setDash([]);C.circle(x,H-y,r,fill=int(fill!='none'),stroke=1)
 svg.append(f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" stroke="{stroke}"/>')
def txt(x,y,t,size=11,color=INK,font='Sans'):
 C.setFillColor(col(color));C.setFont(font,size);C.drawString(x,H-y,t)
 svg.append(f'<text x="{x}" y="{y}" font-family="DejaVu Sans, sans-serif" font-size="{size}" fill="{color}"'+(' font-weight="700"' if font=='Bold' else '')+f'>{html.escape(str(t))}</text>')
def para(x,y,t,width=470,size=12,color=MUT,leading=19):
 words=t.split(); cur='';lines=[]
 for word in words:
  if pdfmetrics.stringWidth((cur+' '+word).strip(),'Sans',size)>width and cur:lines.append(cur);cur=word
  else:cur=(cur+' '+word).strip()
 if cur:lines.append(cur)
 for i,s in enumerate(lines):txt(x,y+i*leading,s,size,color)
 return y+len(lines)*leading

def begin(code,title,sub='Предварительное задание для согласования / не для монтажа',scale='Схема'):
 global svg
 svg=[];rect(0,0,W,H,PAPER,'none');txt(42,42,'ЛЕСНАЯ ПОЛЯНА  /  ЛИЗА',12,font='Bold');txt(870,42,'D / 01   ·   ТИХАЯ ГЕОЛОГИЯ',12)
 line(42,60,W-42,60,LINE);txt(42,101,title,27,font='Serif');txt(43,124,sub,11,RED if 'не для' in sub else MUT)
 rect(42,H-85,W-84,48,'none',LINE);txt(54,H-65,'LP-D01 / '+code,11,font='Bold');txt(280,H-65,'29.09.2026  ·  Редакция 01',10);txt(550,H-65,scale,10);txt(850,H-65,'Лист '+str(len(pages)+1).zfill(2),10)
 txt(54,H-46,'Размеры в мм. Привязки проектные. Геометрия условная: требуется контрольный обмер.',9,MUT)
 pages.append({'id':code,'title':title,'path':f'docs/engineering/{code}.svg','scale':scale})
def end():
 (OUT/(pages[-1]['id']+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" role="img"><title>{html.escape(pages[-1]["title"])}</title>'+''.join(svg)+'</svg>')
 C.showPage()
def xy(x,y):return OX+x*S,OY+y*S
def footprint(o):
 x,y,w,d=o['x'],o['y'],o['width'],o['depth'];cx,cy=x+w/2,y+d/2;a=math.radians(o.get('rotation',0));c,s=math.cos(a),math.sin(a)
 return [(cx+(px-cx)*c-(py-cy)*s,cy+(px-cx)*s+(py-cy)*c) for px,py in [(x,y),(x+w,y),(x+w,y+d),(x,y+d)]]
def dim(a,b,label,dy=0):
 x1,y1=xy(*a);x2,y2=xy(*b);y1+=dy;y2+=dy;line(x1,y1,x2,y2,MUT,.65);line(x1-3,y1+3,x1+3,y1-3,MUT,.65);line(x2-3,y2+3,x2+3,y2-3,MUT,.65);txt((x1+x2)/2-12,(y1+y2)/2-5,str(label),9,MUT)
def plan(furn=True,part=False):
 poly([xy(*p) for p in G['floor']],'#f1efe8',LINE)
 for o in G['walls']:
  if o.get('openingPart'):continue
  poly([xy(*p) for p in footprint(o)],'#444b45','none')
 for o in D['partitions']:
  if o.get('openingPart'):continue
  poly([xy(*p) for p in footprint(o)],ACC if part else '#687269','none')
 for win in G['windows']:
  x,y=xy(win['x'],win['y']);line(x,y,x+win['width']*S,y,BLUE,3)
 for d in D['doors']:
  x,y=xy(d['x'],d['y']);line(x,y,x+d['width']*S,y,ACC,1,True)
 if furn:
  for o in D['furniture']:
   if o['type'] in ['tv','mirror']:continue
   poly([xy(*p) for p in footprint(o)],'#e6dfd2',LINE,.65)
 for room in D['rooms']:
  if room['id'] in ['adult','alice','bath']:
   x,y=xy(room['x']-480,room['y']);txt(x,y,{'adult':'01 / СПАЛЬНЯ','alice':'02 / ДЕТСКАЯ','bath':'03 / САНУЗЕЛ'}[room['id']],9,MUT)
 dim((0,0),(6400,0),6400,-23);dim((0,8300),(3175,8300),3175,25);dim((3425,7440),(6400,7440),2975,25)
 x,y=xy(-500,0);line(x,y,x,y+8300*S,MUT,.65);txt(x-30,y+230,'8300',9,MUT)
 txt(90,681,'0',9);line(101,676,101+1000*S,676,INK,3);txt(164,681,'1 м  /  1:50 на A3',9,MUT)
def note(title,body,y=175):
 txt(590,y,title,15,font='Bold');return para(590,y+29,body,500,12,leading=20)+24

def table(headers,rows,widths,x=48,y=175,size=10,rowh=29):
 xx=x
 for h,w in zip(headers,widths):rect(xx,y,w,27,'#e7e5dd','none');txt(xx+8,y+18,h,size,INK,'Bold');xx+=w
 yy=y+27
 for row in rows:
  maxlines=1;wrapped=[]
  for v,w in zip(row,widths):
   ls=[];cur=''
   for word in str(v).split():
    if pdfmetrics.stringWidth((cur+' '+word).strip(),'Sans',size)>w-16 and cur:ls.append(cur);cur=word
    else:cur=(cur+' '+word).strip()
   ls.append(cur);wrapped.append(ls);maxlines=max(maxlines,len(ls))
  height=max(rowh,maxlines*(size+5)+10);xx=x
  for ls,w in zip(wrapped,widths):
   for j,t in enumerate(ls):txt(xx+8,yy+17+j*(size+5),t,size)
   xx+=w
  line(x,yy+height,x+sum(widths),yy+height,LINE,.6);yy+=height
 return yy
